// Individual Cell Voltage Protection
//
// ACTIVATION:
//   Activates at >= 3.350 V.
//
// HYSTERESIS:
//   Once active, remains active until <= 3.340 V.
//   Between 3.340 V and 3.350 V, holds charge current at 15 A.
//
// RATE LIMIT:
//   Output changes no more than once every 5 seconds.
//
// Change your specific voltages and desired amp throttle here.
//
const points = [
    { v: 3.350, a: 15 },
    { v: 3.375, a: 10 },
    { v: 3.400, a: 5 },
    { v: 3.425, a: 2 },
    { v: 3.450, a: 1 },
    { v: 3.500, a: 0 }
];

const ACTIVATE_VOLTAGE = 3.350;
const RELEASE_VOLTAGE = 3.340;

const voltage = Number(msg.payload);
const now = Date.now();

const lastSend = flow.get('cellProtectionLastSend') || 0;
let active = flow.get('cellProtectionActive') === true;

if (isNaN(voltage)) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "Invalid cell voltage"
    });
    return null;
}

// ============================================================
// INACTIVE — WAIT FOR 3.350 V
// ============================================================

if (!active) {

    if (voltage < ACTIVATE_VOLTAGE) {
        node.status({
            fill: "grey",
            shape: "ring",
            text: voltage.toFixed(3) + " V — protection inactive"
        });
        return null;
    }

    active = true;
    flow.set('cellProtectionActive', true);
}

// ============================================================
// ACTIVE — RELEASE AT 3.340 V
// ============================================================

if (active && voltage <= RELEASE_VOLTAGE) {

    flow.set('cellProtectionActive', false);
    flow.set('cellProtectionLastSend', now);

    node.status({
        fill: "grey",
        shape: "ring",
        text: voltage.toFixed(3) + " V — protection released"
    });

    return null;
}

// ============================================================
// HYSTERESIS BAND: 3.340–3.350 V
// ============================================================

if (voltage < ACTIVATE_VOLTAGE) {

    if (now - lastSend < 5000) {
        node.status({
            fill: "blue",
            shape: "ring",
            text: voltage.toFixed(3) + " V → 15 A (waiting 5s)"
        });
        return null;
    }

    flow.set('cellProtectionLastSend', now);

    msg.payload = 15;

    node.status({
        fill: "yellow",
        shape: "dot",
        text: voltage.toFixed(3) + " V → 15 A"
    });

    return msg;
}

// ============================================================
// RATE LIMIT
// ============================================================

if (now - lastSend < 5000) {
    node.status({
        fill: "blue",
        shape: "ring",
        text: voltage.toFixed(3) + " V (waiting 5s)"
    });
    return null;
}

// ============================================================
// CELL VOLTAGE CURVE
// ============================================================

let current;

if (voltage >= points[points.length - 1].v) {

    current = 0;

} else {

    let i = 0;

    while (
        i < points.length - 1 &&
        voltage > points[i + 1].v
    ) {
        i++;
    }

    const p0 = points[Math.max(i - 1, 0)];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[Math.min(i + 2, points.length - 1)];

    const t = (voltage - p1.v) / (p2.v - p1.v);

    const m1 = 0.5 * (p2.a - p0.a);
    const m2 = 0.5 * (p3.a - p1.a);

    const t2 = t * t;
    const t3 = t2 * t;

    const a = 2 * t3 - 3 * t2 + 1;
    const b = t3 - 2 * t2 + t;
    const c = t3 - t2;
    const d = -2 * t3 + 3 * t2;

    current =
        a * p1.a +
        b * m1 +
        c * m2 +
        d * p2.a;

    current = Math.max(0, Math.min(15, current));
    current = Math.round(current * 10) / 10;
}

// ============================================================
// OUTPUT
// ============================================================

flow.set('cellProtectionLastSend', now);

msg.payload = current;

node.status({
    fill: "green",
    shape: "dot",
    text: voltage.toFixed(3) + " V → " + current + " A"
});

return msg;
